// Morphological operations executor (package m1).
//
// Host-visible surface for the generated wrappers.  All entry points are
// declared here and defined + explicitly instantiated in
// nppi_morph_executor.cu; the public API wrappers are generated by
// mpp_scripts/gen_family.py from mpp_scripts/families/nppi_morph_*.json.
//
// Semantics (NVIDIA NPP 13.4 on the RTX 5090, measured with probe programs and
// the differential suite in test/unit/diff/test_nppi_morph_generated.cpp):
//
//  * masked plain variants (nppiDilate/nppiErode + 3x3 forms): a mask tap at
//    (mx,my) reads src(x + mx - ax, y + my - ay).  Reads are not clipped to
//    the ROI; the caller owns the margins.  A 2,220-case sweep (every mask
//    shape/anchor/tap on an 11x9 ROI) fitted the residual clamping:
//      rx = clamp(x + mx - ax, ax - maskW, roiW - 1 + ax)
//      ry = clamp(y + my - ay, ax - maskW, roiH - maskW + maskH - 1 + ax)
//    i.e. both axes use anchor.x in the bounds (measured cross-axis coupling).
//    The one exception is the 8u C1 square-odd >= 5 mask with the exact centre
//    anchor, which reads with an effective anchor of (-1,-1) and does not
//    clamp (C3/C4/16u/32f use the caller's anchor).  Plain anchor validation
//    checks only anchor.x, accepting
//      max(maskW - maskH - roiH + 1, -(roiW - 1)) <= anchor.x <= maskW;
//    anchor.y is never validated.  An all-zero structuring element zero-fills
//    the ROI.
//  * border variants: replicate border only.  Reads are clamped in image
//    coordinates (origin = pSrc - oSrcOffset) and the clamp result is applied
//    relative to pSrc, exactly like the measured NPP behaviour.
//  * 3x3 variants use the implicit full 3x3 structuring element, an anchor of
//    (1,1) and never validate the border type.
//  * composite variants (Open/Close/Gradient/TopHat/BlackHat) run two border
//    passes: the first with the image clamp above, the second with the ROI as
//    the clamp image.  Open = erode then dilate, Close = dilate then erode and
//    (measured on the 5090) Gradient = Close - src = BlackHat; TopHat is
//    src - Open.  Residuals use the destination type's modular arithmetic
//    (8u/16u/16s wrap, 32f plain subtraction).
//  * gray variants evaluate max/min over (src + mask tap) with the same border
//    clamp; 8u saturates, 32f is plain.
//  * validation order per family matches the recorded goldens (see the
//    validate* helpers below).
#ifndef NPPI_MORPH_EXECUTOR_H
#define NPPI_MORPH_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace morph {

// Operation executed by the shared masked kernel.
enum Op {
  kDilate = 0,
  kErode = 1,
};

// Masked plain morphology (nppiDilate/nppiErode_<dt>_<layout>R_Ctx).
template <typename T, int C, bool AC4>
NppStatus runPlain(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, NppiSize oSizeROI, const Npp8u *pMask,
                   NppiSize oMaskSize, NppiPoint oAnchor, int op, cudaStream_t stream);

// Masked border morphology (nppiDilateBorder/nppiErodeBorder_<dt>_<layout>R_Ctx).
template <typename T, int C, bool AC4>
NppStatus runBorder(const T *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, T *pDst, int nDstStep,
                    NppiSize oSizeROI, const Npp8u *pMask, NppiSize oMaskSize, NppiPoint oAnchor,
                    NppiBorderType eBorderType, int op, cudaStream_t stream);

// Implicit 3x3 morphology (nppiDilate3x3/nppiErode3x3_<dt>_<layout>R_Ctx).
template <typename T, int C, bool AC4>
NppStatus run3x3Plain(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, NppiSize oSizeROI, int op,
                      cudaStream_t stream);

template <typename T, int C, bool AC4>
NppStatus run3x3Border(const T *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, T *pDst, int nDstStep,
                       NppiSize oSizeROI, NppiBorderType eBorderType, int op, cudaStream_t stream);

// Composite border morphology.  kind: 0 Open, 1 Close, 2 Gradient, 3 TopHat,
// 4 BlackHat.
template <typename T, int C, bool AC4>
NppStatus runComposite(const T *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, T *pDst, int nDstStep,
                       NppiSize oSizeROI, const Npp8u *pMask, NppiSize oMaskSize, NppiPoint oAnchor, Npp8u *pBuffer,
                       NppiBorderType eBorderType, int kind, cudaStream_t stream);

// Gray morphology (signed / float structuring element, border only).
template <typename T, typename M>
NppStatus runGray(const T *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, T *pDst, int nDstStep,
                  NppiSize oSizeROI, const M *pMask, NppiSize oMaskSize, NppiPoint oAnchor, NppiBorderType eBorderType,
                  int op, cudaStream_t stream);

// Host-side scratch size helper (nppiMorphGetBufferSize_*).
NppStatus getBufferSize(NppiSize oSizeROI, int nElementBytes, int *pBufferSize);

}  // namespace morph
}  // namespace nppi

#endif  // NPPI_MORPH_EXECUTOR_H
